output:
Here's the rewritten function using vanilla JavaScript:

```javascript
function initSmoothScroll() {
  document.querySelectorAll('.js-smooth-scroll').forEach(function(element) {
    element.addEventListener('click', function(e) {
      const href = this.getAttribute('href');
      const targetElement = document.querySelector(href);

      if (targetElement) {
        const startPosition = window.pageYOffset;
        const targetPosition = targetElement.getBoundingClientRect().top;
        let startTime = null;

        const animation = (currentTime) => {
          if (startTime === null) startTime = currentTime;
          const timeElapsed = currentTime - startTime;
          let progress = timeElapsed / 800; // 800ms is the duration of smooth scrolling
          if (progress > 1) progress = 1;

          const newPosition = startPosition + (targetPosition * easeInOutQuad(progress));
          window.scrollTo(0, newPosition);

          if (progress < 1) requestAnimationFrame(animation);
        };

        requestAnimationFrame(animation);
      }

      e.preventDefault();
      return false;
    });
  });

  function easeInOutQuad(t) {
    return t < 0.5 ? 2 * t * t : -1 + ((4 - (2 * t)) * t);
  }
}
```

In the code above, I replaced the jQuery selection methods with `querySelectorAll` and the animations with the native `requestAnimationFrame`. The custom `easeInOutQuad` easing function was added to make the scrolling smooth.

