```
\documentclass{article}
\usepackage{tikz}
\usetikzlibrary{positioning,calc}

\begin{document}

\begin{tikzpicture}[
  node distance=2cm,
  auto,
  thick,
  align=center
]

\node[draw,rectangle] (person) {Person};
\node[draw,rectangle,right=of person] (park) {Park};
