The following code snippet can be used to analyze the data:

```c++
#include <iostream>
#include <vector>

using namespace std;

int main() {

  // Initialize the data.
  vector<int> energy_generation = {5, 4, 3, 2, 2.5, 1.5};
  vector<string> cloud_types = {"no clouds", "cumulus clouds", "stratus clouds", "cirrus clouds", "cumulus clouds and stratus clouds", "cirrus clouds and stratus clouds"};

  // Calculate the average energy generation for each type of cloud.
  vector<double> average_energy_generation = {};
  for (int i = 0; i < cloud_types.size(); i++) {
    double energy_generation_sum = 0;
    for (int j = 0; j < energy_generation.size(); j++) {
      if (cloud_types[j] == cloud_types[i]) {
        energy_generation_sum += energy_generation[j];
      }
    }
    average_energy_generation.push_back(energy_generation_sum / energy_generation.size());
  }

  // Print the results.
  cout << "The average energy generation for each type of cloud is: " << endl;
  for (int i = 0; i < average_energy_generation.size(); i++) {
    cout << cloud_types[i] << " : " << average_energy_generation[i] << endl;
  }

  return 0;
}
```

