output:
```cpp
#include <vector>
#include <cstring>
#include <iostream>

void run_kmeans(twtown** routes, int lenSub, twtown* sub, double** distance_matrix, double** cluster_centers, int* cluster_assignments, int maxCapacity, twtown town0, int* cnt, const int count_vehicle)
{
    initialize_cluster_centers(count_vehicle, sub, cluster_centers);

    std::vector<int> cluster_sizes(count_vehicle);
    std::vector<std::vector<double>> cluster_sum(count_vehicle, std::vector<double>(DIMENSIONS));
    std::vector<std::vector<double>> tmp_centers(count_vehicle, std::vector<double>(DIMENSIONS));
    std::vector<int> cap(count_vehicle);

    for (int i = 0; i < MAX_ITERATIONS; i++)
    {
        for (int j = 0; j < lenSub - 1; j++)
        {
            for (int k = 0; k < count_vehicle; k++)
            {
                distance_matrix[j][k] = euclidean_distance(sub[j], cluster_centers[k]);
            }
        }

        update_cluster_assignments(sub, lenSub - 1, distance_matrix, cluster_assignments, maxCapacity, count_vehicle, cap.data());
        for (int t = 0; t < count_vehicle; t++)
        {
            cap[t] = 0;
        }

        int stop = update_cluster_centers(lenSub - 1, sub, cluster_assignments, cluster_centers, cnt, count_vehicle, cluster_sizes.data(), cluster_sum, tmp_centers);

        std::fill(cluster_sizes.begin(), cluster_sizes.end(), 0);
        std::fill_n(cluster_sum.begin(), count_vehicle, std::vector<double>(DIMENSIONS));
        std::fill_n(tmp_centers.begin(), count_vehicle, std::vector<double>(DIMENSIONS));

        if (stop)
        {
            break;
        }
    }

    std::fill_n(cnt, count_vehicle, 0);

    for (int j = 0; j < lenSub - 1; j++)
    {
        routes[cluster_assignments[j]][cnt[cluster_assignments[j]]] = sub[j];
        cnt[cluster_assignments[j]]++;
    }

    for (int i = 0; i < count_vehicle; i++)
    {
        routes[i][cnt[i]] = town0;
        cnt[i]++;
    }
}
```

I've replaced some of the C-library based memory allocations with std::vector and removed the manual memory management. The code is now more idiomatic C++ and should provide cleaner and safer memory usage.

