The following is a possible implementation of a library that helps facilitate the creation of the objects at each layer:

```c#
public class BaseObject
{
    public string Id { get; set; }
    public string Name { get; set; }
}

public class CompanyObject : BaseObject
{
    public string Address { get; set; }
}

public class ProductObject : BaseObject
{
    public string Description { get; set; }
    public decimal Price { get; set; }
}

public class LineOfBusinessObject : BaseObject
{
    public string Code { get; set; }
    public string Description { get; set; }
}

public class Library
{
    public static BaseObject CreateBaseObject(string id, string name)
    {
        return new BaseObject
        {
            Id = id,
            Name = name
        };
    }

    public static CompanyObject CreateCompanyObject(string id, string name, string address)
    {
        return new CompanyObject
        {
            Id = id,
            Name = name,
            Address = address
        };
    }

    public static ProductObject CreateProductObject(string id, string name, string description, decimal price)
    {
        return new ProductObject
        {
            Id = id,
            Name = name,
            Description = description,
            Price = price
        };
    }

    public static LineOfBusinessObject CreateLineOfBusinessObject(string id, string code, string description)
    {
        return new LineOfBusinessObject
        {
            Id = id,
            Code = code,
            Description = description
        };
    }
}
```

