  container: {
    flex: 1,
    backgroundColor: '#ffffff',
  },
  text: {
    fontSize: 24,
    textAlign: 'center',
    margin: 20,
  },
});

const SplashScreenOptions = ({ navigation }) => {
  return (
    <NavigationScreenOptions
      headerLeft={null}
      headerRight={null}
      screen={SplashScreen}
    />
  );
};

export default SplashScreenOptions;
```

You can also remove the default header from all screens in your app by setting the `headerMode` prop on the `NavigationContainer` component to `none`. For example:

```
import React from 'react';
import { NavigationContainer } from 'react-navigation';

const App = () => {
  return (
    <NavigationContainer
      headerMode={'none'}
      screen={SplashScreen}
    />
  );
};

export default App;
```

