sub getpasswordage {
 my $username = shift;

 if (!$username) {
 print "Enter username: ";
 $username = <>;
 }
 print "\n";
 chomp $username;
 my $userdn = "uid=$username,ou=Users,dc=sproutsocial,dc=com";

 my $result = $ldap->search( base => $userdn, scope => 'base', filter => "(uid=$username)", attrs => ['shadowLastChange']);
 if (! $result->entry ) {
 print "!!! $username not found in ldap, or does not have a last changed date.\n";
 return 0;
 };
 my $change = $result->entry->get\_value('shadowLastChange');
 if (! $change ) {
 print "!!! $username has never rotated their password - shadowLastChange undefined!\n";
 return 0;
 };

 # "You shouldn't assume the value of the epoch." - Tcl clock manual page
 my $openLdapEpoch = DateTime->new(
 year => 1970,
 month => 1,
 day => 1);
 my $now = DateTime->today();
 my $passChanged = $openLdapEpoch->add(days => $change);
 my $passChangedDateFormatted = $passChanged->strftime('%F');
 my $passChangedAge = $now->delta\_days($passChanged)->delta\_days();
 print "Password for $username last changed on $passChangedDateFormatted, $passChangedAge days ago\n";
}
