To update the existing JavaScript code for the above requirements, you can follow these steps:

1. Write a function to check if a word is an acronym/initialism.
2. Write a function to process the words, handling hyphenated words, and apostrophes.
3. Update the existing code that modifies the input string sentence by integrating the two new functions.

Here's an example implementation:

```javascript
function isAcronym(word) {
  return word.toUpperCase() === word;
}

function processWord(word) {
  let parts = [];

  // Handle hyphenated words
  if (word.includes("-")) {
    parts = word.split("-").map((part) => processWord(part));
    return parts.join("-");
  }

  // Handle words with apostrophes
  if (word.includes("'")) {
    parts = word.split("'").map((part) => processWord(part));
    return parts.join("'");
  }

  if (isAcronym(word)) {
    return word.toUpperCase();
  } else {
    return word.charAt(0).toUpperCase() + word.slice(1).toLowerCase();
  }
}

function processSentence(sentence) {
  const words = sentence.split(" ");
  const processedWords = words.map((word) => processWord(word));
  return processedWords.join(" ");
}

// Example usage of the above implementation
let input = "The quick Brown FOX jumped over the hyphen-TEST and the apostrophe'S test.";
let result = processSentence(input);
console.log(result);
```

