Sure, here is a Java function to calculate the total time length of all classes completed by a student in the Student category:

public static int getTotalTimeLength(String sheetName, String timeLengthData, String categoryData, String studentNameData, String category, String studentName) {
    // Get the data from the spreadsheet
    List<String> timeLengths = getValues(sheetName, timeLengthData);
    List<String> categories = getValues(sheetName, categoryData);
    List<String> studentNames = getValues(sheetName, studentNameData);

    // Calculate the total time length
    int totalTimeLength = 0;
    for (int i = 0; i < timeLengths.size(); i++) {
        if (categories.get(i).equals(category) && studentNames.get(i).equals(studentName)) {
            totalTimeLength += Integer.parseInt(timeLengths.get(i));
        }
    }

    return totalTimeLength;
}

private static List<String> getValues(String sheetName, String columnName) {
    // Get the spreadsheet
    Workbook workbook = new XSSFWorkbook();
    Sheet sheet = workbook.getSheet(sheetName);

    // Get the values from the specified column
    List<String> values = new ArrayList<>();
    for (int i = 0; i < sheet.getRowCount(); i++) {
        values.add(sheet.getRow(i).getCell(sheet.getColumnIndex(columnName)).getStringCellValue());
    }

    return values;
}

