```
# Define the scale and frequencies
scale = ['C','D','E','F','G','A','B'];
freqs = [261.63,293.66,329.63,349.23,392,440,493.88];

# Create the XML document
docNode = com.mathworks.xml.XMLUtils.createDocument('scale');
root = docNode.getDocumentElement;

# Add a note element for each note in the scale
for i = 1:length(scale)
    note = docNode.createElement('note');
    root.appendChild(note);
    name = docNode.createElement('name');
    name.appendChild(docNode.createTextNode(scale(i)));
    note.appendChild(name);
    freq = docNode.createElement('frequency');
    freq.appendChild(docNode.createTextNode(num2str(freqs(i))));
    note.appendChild(freq);
end

# Write the XML file
xmlwrite('scale.xml',docNode);
