import Swift
func correctSentence(sentence: String) -> String? {
    // Validate sentence structure
    let sentencePattern = "^(?:Subjectverbobject)?$"
    if let patternMatch = sentence.match(pattern: sentencePattern),
    let (subject, verb, object) = patternMatch {
        // Correct sentence structure
        let correctedSentence = "\(subject) \(verb) \(object)"
        return correctedSentence

    else {
        // Return error message if sentence structure is invalid
        return "Invalid sentence structure. Please enter a sentence in the subject-verb-object format."
    }

return nil
}

