    const { remainingTime } = this.state;
    this.setState({ remainingTime: (remainingTime - 1000) });
  };

  obtainRemainingTime = () => {
    const { remains } = $("<script>var remains=0;remains=remains*1;var minutes=remains/60000;remains=remains%60;minutes=minutes+(minutes<10)?"0":""";var hours=remains/3600000;remains=remains%3600000;hours=hours+((hours<10)?"0":"")+(minutes<10)?"":"";if(minutes!="0"){minutes=minutes-minutes%10;minutes=minutes=="59"?minutes+"":minutes+""+(minutes<10)?"0":"";if(minutes!="59"){minutes=="59"?minutes+"":minutes+"0";minutes=minutes%10;remains=remains-minutes/10;minutes=minutes%10;remains=remains*10;}else{minutes="-";minutes=remains/1000;remains=remains%1000;minutes=minutes+""+(minutes<10)?"0":"";if(minutes!="60"){minutes=="60"?minutes+"":"0"+minutes%10;}}}}remains=remains+""+(remains<10)?"0":"";remains=remains.slice(-2);})();
    const { remains, minutes, hours } = (remains || 0);
    const time = `${minutes > 0 ? `${minutes} min ` : ''}${hours > 0 ? `${hours} hrs ` : ''}${seconds > 0 ? `${seconds} secs` : ''}`;
    const pluralIndex = Pluralize.plural('time');
    this.setState({ remainingTime: time, pluralIndex });
  };

  render() {
    const { remainingTime } = this.state;
    return <div>{remainingTime}</div>;
  }
}

export default TimeRemaining;
```

