Sure. Here is a sample code for generating a list of synonyms for a given word in C++:

```c++
#include <iostream>
#include <string>
#include <vector>
#include <algorithm>
#include <unordered_map>
#include <fstream>

using namespace std;

int main() {
  string word;
  cin >> word;

  // Get synonyms from a dictionary file.
  ifstream dict("dictionary.txt");
  unordered_map<string, vector<string>> synonyms;
  string line;
  while (getline(dict, line)) {
    istringstream iss(line);
    string word, synonym;
    iss >> word;
    while (iss >> synonym) {
      synonyms[word].push_back(synonym);
    }
  }

  // Generate a list of synonyms for the given word.
  vector<string> results;
  for (auto& synonym : synonyms[word]) {
    results.push_back(synonym);
  }

  // Print the results.
  for (string result : results) {
    cout << result << " ";
  }
  cout << endl;

  return 0;
}
```

This code uses a dictionary file to store a list of synonyms for each word. The dictionary file can be created by hand or by using a dictionary building tool. The code first gets the synonyms for the given word from the dictionary file. Then, it generates a list of all the synonyms and prints them to the console.

Sure. Here is a C program that calculates the power of a given number using recursion:

```c
#include <stdio.h>

int power(int x, int y) {
    if (y == 0) {
        return 1;
    } else if (y % 2 == 0) {
        return power(x, y / 2) * power(x, y / 2);
    } else {
        return x * power(x, y - 1);
    }
}

int main() {
    int x, y;
    printf("Enter x and y: ");
    scanf("%d %d", &x, &y);
    printf("%d to the power of %d is %d\n", x, y, power(x, y));
    return 0;
}
```

This program works by first checking if the exponent is 0. If it is, the program returns 1. Otherwise, the program checks if the exponent is even. If it is, the program calls itself recursively to calculate the power of x to half of the exponent, and then multiplies the result by itself. If the exponent is odd, the program multiplies x by the result of calling itself recursively to calculate the power of x to the exponent minus 1.

