You can modify the JavaScript code to keep track of diagonal wins for each player and declare the winner accordingly. Here's a modified version of your `tic-tac-toe.js` code:

```
let player1 = true;
let player2 = false;
let gameover = false;
let diagonalWinsPlayer1 = 0;
let diagonalWinsPlayer2 = 0;

function check() {
    let diagonalWin1 = (player, id1, id2, id3) => {
        let element1 = document.getElementById(id1);
        let element2 = document.getElementById(id2);
        let element3 = document.getElementById(id3);

        if (element1.innerHTML == player && element2.innerHTML == player && element3.innerHTML == player) {
            if (player == "X") diagonalWinsPlayer1++;
            else diagonalWinsPlayer2++;
        }
    }

    diagonalWin1("X", "1", "5", "9");
    diagonalWin1("X", "3", "5", "7");
    diagonalWin1("O", "1", "5", "9");
    diagonalWin1("O", "3", "5", "7");

    if (diagonalWinsPlayer1 > diagonalWinsPlayer2) {
        alert("Player 1 wins!");
        gameover = true;
    } else if (diagonalWinsPlayer2 > diagonalWinsPlayer1) {
        alert("Player 2 wins!");
        gameover = true;
    }
}

function clicked(id) {
    if (!gameover) {
        if (player1 && document.getElementById(id).innerHTML == "") {
            document.getElementById(id).innerHTML = "X";
            player1 = false;
            player2 = true;
            check();
        } else if (player2 && document.getElementById(id).innerHTML == "") {
            document.getElementById(id).innerHTML = "O";
            player1 = true;
            player2 = false;
            check();
        }
    }
}
```

