```java
import java.util.Scanner;

public class PlanetExplorer {

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        // Get the planet's radius.
        System.out.print("Enter the planet's radius: ");
        double radius = sc.nextDouble();

        // Get the planet's gravitational acceleration.
        System.out.print("Enter the planet's gravitational acceleration: ");
        double g = sc.nextDouble();

        // Get the planet's atmospheric pressure.
        System.out.print("Enter the planet's atmospheric pressure: ");
        double pressure = sc.nextDouble();

        // Get the planet's atmospheric temperature.
        System.out.print("Enter the planet's atmospheric temperature: ");
        double temperature = sc.nextDouble();

        // Get the planet's crust composition.
        System.out.print("Enter the planet's crust composition: ");
        String crust = sc.next();

        // Get the planet's core composition.
        System.out.print("Enter the planet's core composition: ");
        String core = sc.next();

        // Calculate the planet's mass.
        double mass = 4 * Math.pi * radius * radius * radius * g;

        // Calculate the planet's volume.
        double volume = 4 * Math.pi * radius * radius * radius / 3;

        // Calculate the planet's density.
        double density = mass / volume;

        // Calculate the planet's escape velocity.
        double escapeVelocity = Math.sqrt(2 * g * radius);

        // Display the results.
        System.out.println("The planet's mass is " + mass + " kg.");
        System.out.println("The planet's volume is " + volume + " m^3.");
        System.out.println("The planet's density is " + density + " kg/m^3.");
        System.out.println("The planet's escape velocity is " + escapeVelocity + " m/s.");
    }
}
```

