  while (url !== undefined) {
    let data: queryResult = await queryFrApi(url);
    console.log(data);
    totalQueryResult = totalQueryResult.concat(data['$resources']);

    if (data['$links']['$next']) {
      url = data['$links']['$next']['$url'] + '&count=1000';
    } else {
      url = undefined;
    }
  }

  console.log('Total items to send to SQS:', totalQueryResult.length);
  await sendProductsToSQS(SQS_QUEUE_URL, totalQueryResult);

  console.timeEnd('doSomething');
};
```

You'll need to replace `REPLACE_WITH_YOUR_SQS_QUEUE_URL` with the actual SQS queue URL you want to use.

