Here's a Java REST API that incorporates the requirements stated in the prompt:

```java
import javax.persistence.*;
import javax.ws.rs.*;
import javax.ws.rs.core.MediaType;
import javax.ws.rs.core.Response;

@Path("/licenses")
@Produces(MediaType.APPLICATION_JSON)
public class LicenseAdminRest {

    private static EntityManager em;

    @PersistenceContext
    public void setEm(EntityManager em) {
        LicenseAdminRest.em = em;
    }

    @POST
    @Consumes(MediaType.APPLICATION_JSON)
    public Response createLicense(LicenseAdmin licenseAdmin) {
        em.persist(licenseAdmin);
        return Response.created(licenseAdmin).build();
    }

    @PUT
    @Path("/{id}")
    @Consumes(MediaType.APPLICATION_JSON)
    public Response editLicense(@PathParam("id") Long id, LicenseAdmin licenseAdmin) {
        licenseAdmin.setId(id);
        em.merge(licenseAdmin);
        return Response.noContent().build();
    }

    @DELETE
    @Path("/{id}")
    public Response deleteLicense(@PathParam("id") Long id) {
        em.remove(em.getReference(LicenseAdmin.class, id));
        return Response.ok().build();
    }

    @Path("/exists")
    @GET
    @Produces(MediaType.TEXT_PLAIN)
    public Response exists(@QueryParam("prefix") String prefix) {
        return Response.ok(em.createQuery("SELECT COUNT(la) FROM LicenseAdmin la WHERE la.systemPrefix = :prefix", Long.class)
                .setParameter("prefix", prefix)
                .getSingleResult()).build();
    }

    @Path("/{id}")
    @GET
    @Produces(MediaType.APPLICATION_JSON)
    public Response readLicense(@PathParam("id") Long id) {
        LicenseAdmin la = em.getReference(LicenseAdmin.class, id);
        return Response.ok(la).build();
    }

    private String getPrefix(LicenseAdmin admin) {
        return admin.getSystemPrefix().substring(0, 2);
    }

    // Special case for checking if id exists by prefix
    @Path("/{prefix}")
    @GET
    @Produces(MediaType.APPLICATION_JSON)
    public Response checkLicensePrefixed(@PathParam("prefix") String prefix) {
        List<? extends LicenseAdmin> list = em.createQuery("SELECT la FROM LicenseAdmin la WHERE la.systemPrefix = :prefix", LicenseAdmin.class)
                .setParameter("prefix", prefix)
                .getResultList();
        if (list.isEmpty()) {
            return Response.status(Response.Status.NOT_FOUND).build();
        }
        return Response.ok(list.get(0)).build();
    }

    @Path("/{id}/full")
    @GET
    @Produces(MediaType.APPLICATION_JSON)
    public Response getFullIdentifier(@PathParam("id") Long id) {
        LicenseAdmin admin = em.find(LicenseAdmin.class, id);
        String fullIdentifier = getPrefix(admin) + admin.getId();
        return Response.ok(JsonObject.createObjectBuilder()
                .add("partialIdentifier", admin.getId())
                .add("prefix", admin.getSystemPrefix())
                .add("fullIdentifier", fullIdentifier)
                .add("createDate", admin.getCreateDate().toString())
                .add("modifyDate", admin.getModifyDate().toString())
                .build()).build();
    }

}
```

