```python
import collections

def get_trio(words):
  """Gets a trio of words from the given list of words that have the same number of vowels and consonants combined."""
  vowels = set('aeiou')
  consonants = set('bcdfghjklmnpqrstvwxyz')
  words = set(words)
  trio = []
  while trio == []:
    for word in words:
      if len(vowels & set(word)) == len(consonants & set(word)):
        trio.append(word)
        break
  return trio

def concatenate_words(words):
  """Concatenates the given words in the order A, B, and C."""
  return ''.join(words)

def capitalize_every_other_character(string):
  """Capitalizes every other character starting from the second character in the given string."""
  return ''.join(c.capitalize() if i % 2 == 0 else c for i, c in enumerate(string))

def replace_e_with_ampersand(string):
  """Replaces all occurrences of the letter "e" with the symbol "&" in the given string."""
  return string.replace('e', '&')

def output_string(string):
  """Outputs the given string in reverse alphabetical order."""
  print(string[::-1])

def main():
  """Gets a list of 500 words from the user and prints the result of the given function."""
  words = input('Enter 500 words: ')
  words = words.split()
  trio = get_trio(words)
  string = concatenate_words(trio)
  string = capitalize_every_other_character(string)
  string = replace_e_with_ampersand(string)
  output_string(string)

if __name__ == '__main__':
  main()
```

