            return
        }

        locationManager.requestLocationUpdates(LocationManager.GPS_PROVIDER, 0, 0, object : LocationListener() {
            override fun onLocationChanged(location: Location) {
                textView.text = "Current weather: ${location.weather} / ${location.temperature}°F"
            }

            override fun onStatusChanged(provider: String, status: Int, extras: Bundle?) {
                Log.d("Location", "Location status changed")
