\node (fallingaction) at (4.5,1.5) {Falling Action};
\node (resolution) at (6,0) {Resolution};

\draw[->] (exposition) -- (risingaction);
\draw[->] (risingaction) -- (climax);
\draw[->] (climax) -- (fallingaction);
\draw[->] (fallingaction) -- (resolution);
\end{tikzpicture}
\end{code}

