```javascript
import React, { Dispatch, useState } from 'react';
import {
  Box,
  Button,
  FormControl,
  FormLabel,
  Input,
  Stack,
  useDisclosure,
} from '@chakra-ui/react';
import { api } from '../utils';

export default function Library({ setInputMessage }) {
  const utils = api.useContext();
  const [selectedTargetPrompt, setSelectedTargetPrompt] = useState('');
  const [editedName, setEditedName] = useState('');
  const [editedPrompt, setEditedPrompt] = useState('');

  const prompts = api.prompt.all.useQuery();
  const { isOpen, onOpen, onClose } = useDisclosure();

  const upsertPrompt = api.prompt.upsert.useMutation({
    onSuccess: async () => utils.prompt.invalidate(),
  });

  const deletePrompt = api.prompt.delete.useMutation({
    onSuccess: async () => utils.prompt.invalidate(),
  });

  return (
    <>
      <Button
        variant="ghost"
        alignSelf={'flex-end'}
        onClick={() => {
          setSelectedTargetPrompt('');
          setEditedPrompt('');
          setEditedName('');
          onOpen();
        }}
      >
        Saved prompts
      </Button>

      {prompts.data
        ?.sort((a, b) => b.updatedAt.getTime() - a.updatedAt.getTime())
        .map((p) => (
          <Stack key={p.id} onClick={() => setInputMessage(p.prompt)} gap={2}>
            <Box>{p.name}</Box>
            <Box>{p.prompt}</Box>
            <Button
              variant="ghost"
              alignSelf={'flex-end'}
              onClick={(e) => {
                e.stopPropagation();
                setSelectedTargetPrompt(p.id);
                setEditedPrompt(p.prompt);
                setEditedName(p.name);
                onOpen();
              }}
            >
              Edit
            </Button>
          </Stack>
        ))}
    </>
  );
}
