public static double GetTimeEstimate(double distance, TerrainType terrain, WeatherCondition weather, double averageSpeed)
{
    double speedModifier = 1.0;

    switch (terrain)
    {
        case TerrainType.Easy:
            speedModifier *= 1.0;
