Sure, here is a C++17 thread pool class:

```c++
#include <thread>
#include <vector>
#include <queue>
#include <mutex>
#include <condition_variable>

class ThreadPool {
public:
  ThreadPool(size_t n_threads) : n_threads(n_threads), threads(n_threads) {
    for (size_t i = 0; i < n_threads; ++i) {
      threads[i] = std::thread([this]() {
        while (true) {
          std::unique_lock<std::mutex> lock(mutex);
          condition_variable cv;
          cv.wait(lock, [this]() { return !tasks.empty(); });
          Task task = tasks.front();
          tasks.pop();
          lock.unlock();
          task();
        }
      });
    }
  }

  ~ThreadPool() {
    for (auto& thread : threads) {
      if (thread.joinable()) {
        thread.join();
      }
    }
  }

  void add_task(std::function<void()> task) {
    std::lock_guard<std::mutex> lock(mutex);
    tasks.push(task);
    condition_variable cv;
    cv.notify_one();
  }

private:
  size_t n_threads;
  std::vector<std::thread> threads;
  std::queue<std::function<void()>> tasks;
  std::mutex mutex;
  std::condition_variable condition_variable;
};
```

This class is a simple thread pool that can be used to run multiple tasks in parallel. The `ThreadPool` class takes a single argument, which is the number of threads to create. The `add_task()` method can be used to add a task to the pool, and the `~ThreadPool()` method will wait for all of the tasks in the pool to finish before exiting.

