\end{figure}

\chapapp{Chapters with Appendices}
\begin{appendices}
    \appendix{Appendix A}
    \begin{figure}[A1]
        \centering
        \includegraphics[scale=0.5]{fig8}
        \caption{Figures are numbered in order of appearance and referenced to the corresponding \autocite{campaign}.}
    \end{figure}
    \appendix{Appendix B}
