Here's a Swift program demonstrating the radix sort algorithm:

```swift
import Foundation

// Helper function to get the maximum number in the given array.
func getMax(_ arr: [Int]) -> Int {
    var max = arr[0]
    for i in 1..<arr.count {
        if arr[i] > max {
            max = arr[i]
        }
    }
    return max
}

// Helper function to perform counting sort on a specified digit place.
func countingSort(_ arr: inout [Int], _ exp: Int) {
    let n = arr.count
    var output = Array(repeating: 0, count: n)
    var count = Array(repeating: 0, count: 10)

    // Store count of occurrences in count[]
    for i in 0..<n {
        count[(arr[i] / exp) % 10] += 1
    }

    // Change count[i] such that it now contains the actual
    // position of this digit in output[]
    for i in 1..<10 {
        count[i] += count[i - 1]
    }

    // Build the output array
    var i = n - 1
    while i >= 0 {
        output[count[(arr[i] / exp) % 10] - 1] = arr[i]
        count[(arr[i] / exp) % 10] -= 1
        i -= 1
    }

    // Copy the output array to the original array
    for i in 0..<n {
        arr[i] = output[i]
    }
}

// Radix Sort function
func radixSort(_ arr: inout [Int]) {
    // Find the maximum number to know the maximum number of digits
    let max = getMax(arr)

    // Do counting sort for every digit
    var exp = 1
    while max / exp > 0 {
        countingSort(&arr, exp)
        exp *= 10
    }
}

// Demo
var arr = [170, 45, 75, 90, 802, 24, 2, 66]
print("Unsorted array: \(arr)")
radixSort(&arr)
print("Sorted array: \(arr)")
```

This program demonstrates the radix sort algorithm to sort an array of integers in ascending order. The `radixSort` function sorts the array by digit levels. It does this by using a helper function, `countingSort`, to sort the input array based on a specified digit place.

`getMax` is another helper function that returns the maximum number in the given array, which is used to determine the number of digit levels to sort.

After defining the helper functions, the main program creates an example integer array, prints the array before sorting, calls the `radixSort` function to sort the array, and then prints the sorted array after sorting.

Using the "node-nlp" library, here's a basic example of a chatbot in JavaScript:

1. First, install the library by running `npm install node-nlp` in your project folder.
2. Create a file named `chatbot.js` in your project folder and add the following code:

```javascript
const { NlpManager } = require('node-nlp');

async function main() {
  // Create an NLP manager instance with language support
  const manager = new NlpManager({ languages: ['en'] });

  // Train the model
  manager.addDocument('en', 'hello', 'greetings.hello');
  manager.addDocument('en', 'hi', 'greetings.hello');
  manager.addDocument('en', 'how are you', 'question.howAreYou');
  manager.addDocument('en', 'what\'s up', 'question.howAreYou');

  manager.addAnswer('en', 'greetings.hello', 'Hello there!');
  manager.addAnswer('en', 'greetings.hello', 'Hi!');
  manager.addAnswer('en', 'question.howAreYou', 'I am doing well, thank you.');
  manager.addAnswer('en', 'question.howAreYou', 'Fine, and you?');

  await manager.train();

  async function chatBotResponse(userInput) {
    const response = await manager.process('en', userInput);
    return response.answer;
  }

  // Test chatbot responses
  const reply1 = await chatBotResponse('hi');
  console.log(reply1); // Hello there! or Hi!

  const reply2 = await chatBotResponse('how are you');
  console.log(reply2); // I am doing well, thank you. or Fine, and you?
}

// Run the chatbot
main().catch(console.error);
```

3. Run `node chatbot.js` in your project folder. It should log the chatbot's responses to the console.

This example is a simple, single-file chatbot built using the NLP manager from the "node-nlp" library. You can add more questions and answers by updating the training data with `addDocument` and `addAnswer` methods accordingly.

