        "Url": "http://localhost:8080"
      },
      "Https": {
        "Url": "https://localhost:8081"
      }
    }
  },
  "Logging": {
    "LogLevel": {
      "Default": "Information",
      "Microsoft": "Warning",
      "Microsoft.Hosting.Lifetime": "Information"
    }
  },
  "AllowedHosts": "*"
}
```

5. To test the `/api/posts` endpoint, use a tool like Postman or curl:

```
curl -X POST -H "Content-Type: application/json" -d '{"id": 1, "title": "My Post", "content": "Hello, world!"}' http://localhost:8080/api/posts
```

This will return the same JSON object you sent:

```json
{
  "id": 1,
  "title": "My Post",
  "content": "Hello, world!"
}
```

