To create a Node.js server with Passport authentication for user login and secure access to restricted content, you'll need to follow these steps:

1. Set up a new Node.js project and install the required dependencies, including Passport.js, Express.js, and a database management system like MongoDB or MySQL.
2. Configure Passport.js to work with your chosen authentication providers, such as Google, Facebook, or Twitter. This will allow users to log in to your server using their social media accounts.
3. Implement effective password hashing for user security. This can be done using a library like Bcrypt or Argon2.
4. Create a user authentication system using Passport.js, which will handle user registration, login, and session management.
5. Restrict access to certain routes and APIs based on user authentication status.
6. Test the system for common vulnerabilities, such as SQL injection, cross-site scripting (XSS), and cross-site request forgery (CSRF).
7. Ensure that the server adheres to best practices for secure authentication and session management, such as using HTTPS, secure cookies, and proper session expiration.
8. Document the system for users and developers, including instructions for setting up and configuring the server, as well as API documentation for developers who want to integrate with your server.

Here's an example of a simple Node.js server with Passport authentication using Google OAuth:
```javascript
const express = require('express');
const passport = require('passport');
const GoogleStrategy = require('passport-google-oauth20').Strategy;
const mongoose = require('mongoose');

const app = express();

// Connect to MongoDB
mongoose.connect('mongodb://localhost/myapp', { useNewUrlParser: true, useUnifiedTopology: true });

// Initialize Passport
passport.use(new GoogleStrategy({
  clientID: 'YOUR_CLIENT_ID',
  clientSecret: 'YOUR_CLIENT_SECRET',
  callbackURL: 'http://localhost:3000/auth/google/callback'
}, function(accessToken, refreshToken, profile, cb) {
  // User authentication logic
  const user = new User({
    email: profile.emails[0].value,
    name: profile.displayName,
    googleId: profile.id
  });
  user.save((err) => {
    if (err) {
      return cb(err);
    }
    cb(null, user);
  });
}));

passport.serializeUser((user, cb) => {
  cb(null, user.id);
});

passport.deserializeUser((id, cb) => {
  User.findById(id, (err, user) => {
    if (err) {
      return cb(err);
    }
    cb(null, user);
  });
});

// Restrict access to certain routes
app.get('/ restricted', passport.authenticate('google', { session: false }), (req, res) => {
  res.send('Welcome,'+ req.user.name + '!');
});

// Login page
app.get('/login', (req, res) => {
  res.render('login', {
    title: 'Login',
    message: 'Please enter your Google credentials'
  });
});

// Login callback
app.get('/auth/google/callback', passport.authenticate('google', { failureRedirect: '/login', successRedirect: '/' }), (req, res) => {
  res.send('Welcome,'+ req.user.name + '!');
});

// Logout
app.get('/logout', (req, res) => {
  req.logout();
  res.redirect('/');
});

app.listen(3000, () => {
  console.log('Server started on port 3000');
});
```
This example uses Google OAuth for authentication, but you can replace it with other authentication providers, such as Facebook or Twitter, by using their respective strategies provided by Passport.js.

Remember to handle errors and exceptions properly, and test your server thoroughly for security vulnerabilities and proper functionality.

