    // Click on the 'Make Offer' button
    cy.get('[data-cy=make-offer-button]').click();

    // Check if the Offer Modal is visible
    cy.get('[data-cy=offer-modal]').should('be.visible');

    // Select 'Non-Instant Buy' option
