This is the manifest file for the extension, which defines the basic information and permissions for the extension.

1. Create a file called `contentScript.js` in the same directory, and add the following content:
```javascript
function isWalletAddress(str) {
  return /^[A-Za-z0-9]{33}$/.test(str);
}

function isContact(str) {
  return /^[A-Za-z0-9_]{33}$/.test(str);
}

function createContextMenu(item) {
  var menu = {
    "items": [
      {
        "title": "Tezos Wallet",
        "icon": "icon.png",
        "contexts": ["selection"],
        "action": function(parameter) {
          chrome.tabs.create({
            url: "https://tzkt.io/" + item
          });
        }
      }
    ]
  };
  return menu;
}

function contextMenuClicked(item) {
  var selection = document.getSelection();
  if (isWalletAddress(selection) || isContact(selection)) {
    chrome.contextMenus.create({
      id: 1,
      title: "Tezos Wallet",
      items: createContextMenu(selection)
    });
  }
}

document.addEventListener("contextmenu", contextMenuClicked);
```
This content script defines a function `isWalletAddress` and `isContact` to check if the selection is a Tezos wallet address or contact, respectively. It also defines a function `createContextMenu` to create a context menu with a link to tzkt.io for the selected text. Finally, it adds an event listener to the `contextmenu` event to call `createContextMenuClicked` when the context menu is clicked.

