To receive a push alert from Firebase Cloud Messaging (FCM) on an iOS app using Swift, you'll first need to set up your project on Firebase, add the required SDKs to your app, and configure the app's capabilities.

Once you've set this up, follow these steps:

Step 1: Import the required modules in `AppDelegate.swift`:

```swift
import UIKit
import UserNotifications
import Firebase
```

Step 2: In the `application(_:didFinishLaunchingWithOptions:)` method, configure Firebase and register for remote notifications:

```swift
func application(_ application: UIApplication, didFinishLaunchingWithOptions launchOptions: [UIApplication.LaunchOptionsKey: Any]?) -> Bool {
    // Configure Firebase
    FirebaseApp.configure()

    // Register for remote notifications
    UNUserNotificationCenter.current().delegate = self
    let authOptions: UNAuthorizationOptions = [.alert, .badge, .sound]
    UNUserNotificationCenter.current().requestAuthorization(options: authOptions, completionHandler: {_, _ in })

    application.registerForRemoteNotifications()

    return true
}
```

Step 3: Add the following methods to handle the device token and receive remote notifications:

```swift
//MARK: - Remote Notifications

func application(_ application: UIApplication, didRegisterForRemoteNotificationsWithDeviceToken deviceToken: Data) {
    Messaging.messaging().apnsToken = deviceToken
}

func application(_ application: UIApplication, didFailToRegisterForRemoteNotificationsWithError error: Error) {
    print("Failed to register for remote notifications: \(error.localizedDescription)")
}

func application(_ application: UIApplication, didReceiveRemoteNotification userInfo: [AnyHashable : Any], fetchCompletionHandler completionHandler: @escaping (UIBackgroundFetchResult) -> Void) {
    Messaging.messaging().appDidReceiveMessage(userInfo)
    handleReceivedRemoteNotification(userInfo)
    completionHandler(.newData)
}

func handleReceivedRemoteNotification(_ notificationData: [AnyHashable : Any]) {
    guard let aps = notificationData["aps"] as? [String: AnyObject] else {
        return
    }
    let alert = aps["alert"] as? String ?? "You have a new message"
    let alertController = UIAlertController(title: "Push Notification", message: alert, preferredStyle: .alert)
    alertController.addAction(UIAlertAction(title: "OK", style: .default, handler: nil))

    UIApplication.shared.keyWindow?.rootViewController?.present(alertController, animated: true, completion: nil)
}
```

Step 4: Conform to the `UNUserNotificationCenterDelegate` and `MessagingDelegate` protocols to handle token refresh and notification presentation:

```swift
class AppDelegate: UIResponder, UIApplicationDelegate, UNUserNotificationCenterDelegate, MessagingDelegate {
    //...
}

//MARK: - UNUserNotificationCenterDelegate

func userNotificationCenter(_ center: UNUserNotificationCenter, willPresent notification: UNNotification, withCompletionHandler completionHandler: @escaping (UNNotificationPresentationOptions) -> Void) {
    handleReceivedRemoteNotification(notification.request.content.userInfo)
    completionHandler([.alert, .badge, .sound])
}

func userNotificationCenter(_ center: UNUserNotificationCenter, didReceive response: UNNotificationResponse, withCompletionHandler completionHandler: @escaping () -> Void) {
    handleReceivedRemoteNotification(response.notification.request.content.userInfo)
    completionHandler()
}

//MARK: - MessagingDelegate

func messaging(_ messaging: Messaging, didReceiveRegistrationToken fcmToken: String?) {
    print("Firebase registration token: \(fcmToken ?? "")")
}
```

