import java.util.Scanner;

public class AmusementPark {

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        // Ask the user how many tickets they want to purchase.
        System.out.println("How many tickets would you like to purchase?");
        int tickets = scanner.nextInt();

        // Calculate the cost of the tickets.
        double ticketPrice = 20.0;
        double totalTicketCost = ticketPrice * tickets;

        // Ask the user what rides they want to go on.
        System.out.println("What rides would you like to go on?");
        String[] rides = scanner.nextLine().split(" ");

        // Calculate the cost of the rides.
        double ridePrice = 10.0;
        double totalRideCost = 0.0;
        for (String ride : rides) {
            totalRideCost += ridePrice;
        }

        // Ask the user what food they want to eat.
        System.out.println("What food would you like to eat?");
        String[] food = scanner.nextLine().split(" ");

        // Calculate the cost of the food.
        double foodPrice = 5.0;
        double totalFoodCost = 0.0;
        for (String food : food) {
            totalFoodCost += foodPrice;
        }

        // Print the total cost of the trip.
        System.out.println("The total cost of your trip is $" + (totalTicketCost + totalRideCost + totalFoodCost));

        // Simulate waiting in line for rides.
        for (String ride : rides) {
            System.out.println("Waiting in line for " + ride + " for 30 minutes.");
            Thread.sleep(1800000);
        }

        // Simulate eating food.
        for (String food : food) {
            System.out.println("Eating " + food + " for 15 minutes.");
            Thread.sleep(900000);
        }

        // Simulate unexpected events, such as ride closures or inclement weather.
        System.out.println("The " + rides[0] + " ride is closed due to technical difficulties.");
        Thread.sleep(300000);
        System.out.println("It's raining. You decide to go back to your hotel and relax.");
        Thread.sleep(600000);
    }
}

