Here's an example localScript for a simple gun in Unity 2D that shoots prefabs towards the direction of the cursor:

```
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.UI;
using TMPro;

public class GunScript : MonoBehaviour
{
    public List<GunPrefab> gunPrefabs = new List<GunPrefab>();
    public TextMeshProUGUI gunName;
    private string selectedGun;
    private enum SelectedGun { MachineGun, RocketLauncher };

    void Start()
    {
        if (gunName)
            gunName.text = "Loading...";

        else
            gunName = GetComponentInChildren<TextMeshProUGUI>();
    }

    void Update()
    {
        if (Input.GetMouseButtonDown(0))
        {
            RaycastHit2D hit = Physics2D.Raycast(Camera.main.ScreenPointToRay(Input.mousePosition), out float dist);
            if (hit.collider == null)
            {
                gunName.text = "Not loaded yet";
                return;
            }

            bool triggerPressed = Input.GetMouseButtonDown(1);

            for (int i = 0; i < gunPrefabs.Count; i++)
            {
                if (gunPrefabs[i].Select == dist && triggerPressed)
                {
                    selectedGun = gunPrefabs[i].Name;
                    break;
                }
            }

            if (!gunPrefabs[selectedGun].Select < dist || triggerPressed)
            {
                gunName.text = "Not loaded yet";
                return;
            }

            gunName.text = gunPrefabs[selectedGun].Name;
            Instantiate(gunPrefabs[selectedGun].Prefab, hit.point, Quaternion.LookRotation(hit.normal));
        }

        if (Input.GetKey(KeyCode.Space))
        {
            gunPrefabs.RemoveAt(selectedGun);
            selectedGun = gunPrefabs.Count - 1;

            foreach (GunPrefab prefab in gunPrefabs)
                prefab.Select = float.MaxValue;

            foreach (string reReference in gunPrefabs)
            {
                var gunPrefab = GetComponent(reReference);
                if (gunPrefab != null)
                {
                    gunPrefabs.Add(new GunPrefab(reReference, gunPrefab.gameObject));
                }
            }

            gunName.text = gunPrefabs[selectedGun].Name;
            gunName.transform.localPosition = new Vector3(100, 100, 10);
            gunName.SetTextColor(gunPrefabs[selectedGun].color);
        }
    }

    private void OnMouseExit()
    {
        gunName.text = "Loading...";
    }
}
```

This script creates a collection of gun prefabs to load and shoot out, and uses the direction of the cursor to select which gun to fire. When a gun is selected, the script instantiates a new instance of the prefab at the cursor position. The script also removes guns and adjusts their position and color upon selection.

