const users = [];
function registerUser(username, password) {
  const user = {
    username: username,
    password: password
  };

  // Check if user already exists
  const existingUser = users.find(u => u.username === username);
  if (existingUser) {
    return { success: false, message: 'User already exists' };
  }

  // Add user to array
  users.push(user);

  return { success: true, message: 'User registered successfully' };
}
function loginUser(username, password, otp) {
  // Find user in array
  const user = users.find(u => u.username === username);

  // Check if user exists and password is correct
  if (!user || user.password !== password) {
    return { success: false, message: 'Invalid username or password' };
  }

  // Check if two-factor authentication is required and if OTP is correct
  if (user.twoFactor && user.otp !== otp) {
    return { success: false, message: 'Invalid OTP' };
  }

  // Generate session token and store in user object
  const sessionToken = generateSessionToken();
  user.sessionToken = sessionToken;

  return { success: true, message: 'Login successful', sessionToken };
}
function resetPassword(username, oldPassword, newPassword) {
