% define conversion factors
metric_cups_to_tbs = 16.6667;
imperial_cups_to_tbs = 15;
% prompt user for input amount in cups
cups = input('Enter the amount of cups: ');
% check if using metric or imperial measurements
measurement = input('Enter "metric" or "imperial" for your measurement system: ', 's');
% perform conversion based on measurement system
if strcmp(measurement, 'metric')
    tablespoons = cups * metric_cups_to_tbs;
else
    tablespoons = cups * imperial_cups_to_tbs;
end
% display result
fprintf('%g cups is equal to %g tablespoons.\n', cups, tablespoons);

