#!/bin/bash

# This script will construct a category-based comparative analysis of domestic animals in Swift, specifically evaluating physical characteristics, behavior, and environmental adaptability of felines, canines, and equines.

# Import the necessary libraries.
import Foundation

# Define the data structure to store the animal information.
struct Animal {
    var name: String
    var physicalCharacteristics: [String]
    var behavior: [String]
    var environmentalAdaptability: [String]
}

# Define the categories to be used in the analysis.
enum Category {
    case physicalCharacteristics
    case behavior
    case environmentalAdaptability
}

# Create a dictionary of animals.
let animals = [
    "Cat": Animal(name: "Cat", physicalCharacteristics: ["Felis catus", "Domestic cat", "Meow", "Pounce", "Hunt", "Scratch", "Lick", "Purr"], behavior: ["Independent", "Curious", "Playful", "Agile", "Predatory"], environmentalAdaptability: ["Lives in a variety of habitats", "Adaptable to different climates", "Can survive in both indoor and outdoor environments"]),
    "Dog": Animal(name: "Dog", physicalCharacteristics: ["Canis lupus familiaris", "Domestic dog", "Woof", "Bark", "Fetch", "Guard", "Protect", "Whine"], behavior: ["Loyal", "Friendly", "Obedient", "Playful", "Herding"], environmentalAdaptability: ["Lives in a variety of habitats", "Adaptable to different climates", "Can survive in both indoor and outdoor environments"]),
    "Horse": Animal(name: "Horse", physicalCharacteristics: ["Equus ferus caballus", "Domestic horse", "Neigh", "Gallop", "Pull cart", "Carry rider", "Swish tail"], behavior: ["Strong", "Energetic", "Fearless", "Playful", "Herding"], environmentalAdaptability: ["Lives in a variety of habitats", "Adaptable to different climates", "Can survive in both indoor and outdoor environments"])
]

# Loop through the animals and extract the relevant information.
for (name, animal) in animals.enumerated() {
    // Extract the physical characteristics.
    let physicalCharacteristics = animal.physicalCharacteristics.map { $0 }

    // Extract the behavior.
    let behavior = animal.behavior.map { $0 }

    // Extract the environmental adaptability.
    let environmentalAdaptability = animal.environmentalAdaptability.map { $0 }

    // Construct the analysis string.
    let analysisString = """
    | Name | Physical characteristics | Behavior | Environmental adaptability |
    |---|---|---|---|
    | \(name) | \(physicalCharacteristics) | \(behavior) | \(environmentalAdaptability) |
    """

    // Print the analysis string.
    print(analysisString)
}


