Sure. Here is a code snippet to extract and sort the market capitalization data for the top five tech companies in 2020:

```
package main

import (
    "fmt"
    "sort"
)

type Company struct {
    Name       string
    MktCap     float64
}

type ByMktCap []Company

func (a ByMktCap) Len() int           { return len(a) }
func (a ByMktCap) Swap(i, j int)      { a[i], a[j] = a[j], a[i] }
func (a ByMktCap) Less(i, j int) bool { return a[i].MktCap > a[j].MktCap }

func main() {
    companies := []Company{
        {Name: "Apple", MktCap: 1752.93},
        {Name: "Microsoft", MktCap: 1532.05},
        {Name: "Amazon", MktCap: 1519.02},
        {Name: "Alphabet", MktCap: 1166.88},
        {Name: "Facebook", MktCap: 701.49},
        {Name: "Tesla", MktCap: 585.27},
    }
    sort.Sort(ByMktCap(companies))
    fmt.Println("Top five tech companies by market capitalization in 2020:")
    for i := 0; i < 5; i++ {
        fmt.Printf("%d. %s (%.2fB)\n", i+1, companies[i].Name, companies[i].MktCap)
    }
}
