Certainly! I can provide you with an efficient QuickSort implementation in C#. The following function named "QuickSort" accepts a list of integers and utilizes the Lomuto partition scheme and median-of-three pivot selection method to improve performance. Here's the code:

```csharp
using System;
using System.Collections.Generic;

public class QuickSortImproved
{
    public static List<int> QuickSort(List<int> numbers)
    {
        if (numbers.Count <= 1)
            return numbers;

        int pivotIndex = SelectPivot(numbers);
        int pivotValue = numbers[pivotIndex];
        numbers.Swap(pivotIndex, numbers.Count - 1);

        int storeIndex = 0;
        for (int i = 0; i < numbers.Count - 1; i++)
        {
            if (numbers[i] < pivotValue)
            {
                numbers.Swap(i, storeIndex);
                storeIndex++;
            }
        }

        numbers.Swap(storeIndex, numbers.Count - 1);

        List<int> left = QuickSort(numbers.GetRange(0, storeIndex));
        List<int> middle = numbers.GetRange(storeIndex, 1);
        List<int> right = QuickSort(numbers.GetRange(storeIndex + 1, numbers.Count - storeIndex - 1));

        left.AddRange(middle);
        left.AddRange(right);
        return left;
    }

    private static int SelectPivot(List<int> numbers)
    {
        int left = 0;
        int mid = numbers.Count / 2;
        int right = numbers.Count - 1;

        if (numbers[left] > numbers[mid])
            numbers.Swap(left, mid);
        if (numbers[left] > numbers[right])
            numbers.Swap(left, right);
        if (numbers[mid] > numbers[right])
            numbers.Swap(mid, right);

        return mid;
    }

    private static void Swap<T>(this IList<T> list, int indexA, int indexB)
    {
        T tmp = list[indexA];
        list[indexA] = list[indexB];
        list[indexB] = tmp;
    }
}
```

To use the "QuickSort" function, create a C# console application, add the above class, and then incorporate the following code in the "Main" entry point:

```csharp
