@functools.lru\_cache(maxsize=2048)
def encode\_nphotos(spec, max\_nphotos=40, dtype=torch.float):
 """Encode number of photos string such as '1,2,3' to a vector with ones
 in corresponding indices. e.g:

 '1, 2, 3' => [0, 1, 1, 1, 0, 0, ...]
 """
 if spec == '':
 return -torch.ones(max\_nphotos, dtype=dtype)

 indices1 = [int(s.strip()) for s in spec.strip(', ').split(',')]

