1. In actions/graphActions.js, remove the fetchData dependency from the useEffect in VisNetwork:

```javascript
 useEffect(() => {
   dispatch(fetchData());
 }, [dispatch]);
```

2. Make sure to return a new object in the reducer, rather than modifying the existing state object, in graphReducer.js:

```javascript
const graphReducer = (state = initialState, action) => {
  switch (action.type) {
    case 'FETCH_GRAPH_DATA_LOADING':
      return {
        ...state,
        loading: true,
      };
    case 'FETCH_GRAPH_DATA':
      return {
        ...state,
        nodes: action.payload.nodes.map((node) => ({ ...node })),
        edges: action.payload.edges.map((edge) => ({ ...edge })),
        loading: false,
      };
    default:
      return state;
  }
};
```

